      "confidence": 0.9
    },
    {
      "claim": "In controlled experiments, models behave like single-hypothesis trackers, anchoring on the diagnosis suggested by opening findings and recovering a second condition mainly when a finding in view points to it.",
      "source_id": "35f37f152c05e59c",
      "evidence_quote": "In controlled experiments, models behave like single-hypothesis trackers: they anchor on the diagnosis suggested by the opening findings, keep questioning around it, and recover a second condition mainly when a finding in view points to it.",
      "confidence": 0.85
    }
  ]
